"""Renders plugins/gaps.md: what the mechanical split could not separate."""
from collections import defaultdict
from pathlib import Path

import model
import plan as plan_mod


def render(plan, tiers):
    out = ['# Gaps left by the plugin split\n',
           'Generated by `tools/split-plugins/split_plugins.py apply`. Everything under `plugins/` builds without\n'
           'the others and nothing in `server` or `client` can see a plugin. These are the places where that\n'
           'could not be achieved by moving files, and what was done instead.\n']

    out += ['\n## Plugin classes that stay in core\n']
    if not plan.kept:
        out += ['None: core code uses no plugin class.\n']
    else:
        out += ['Core code uses these classes, directly or through another class that stays. They are still in the\n'
                'plugin packages and compile with `server`; the core jars (`mirth-client-core.jar` for shared\n'
                'classes, `mirth-server.jar` otherwise) ship them instead of the extension jars.\n'
                'Removing a gap means changing the core code that uses it (usually by giving core a model of its own).\n\n',
                '| Class | Why |\n|---|---|\n']
        for path, why in sorted(plan.kept.items()):
            cls = path.split('/java/')[1][:-5].replace('/', '.')
            out.append(f'| `{cls}` | {why} |\n')

    out += ['\n## Classes assigned to a plugin from another package\n',
            'These keep their package names, so scripts and serialized data are unaffected, but ship in the plugin\'s jars\n'
            '(`model.OWNERSHIP_OVERRIDES`).\n\n']
    out += [f'- `{k.replace("/", ".")}` -> `{e}:{t}`\n' for k, (e, t) in sorted(model.OWNERSHIP_OVERRIDES.items())]

    out += ['\n## Promoted to the shared jar\n',
            'A shared class must not depend on server-only classes of its plugin; these were moved to `common`.\n\n']
    out += [f'- `{p.split("/java/")[1][:-5].replace("/", ".")}` ({why})\n' for p, why in sorted(plan.promoted.items())] or ['- none\n']

    out += ['\n## Plugin libraries core compiles against\n',
            'Core classes import these third-party libraries, so `server` compiles against them (`compileOnly`) although they are\n'
            'shipped by the plugin. Vendored jars of that kind stay in `server/lib/extensions` and the plugin packages them from there.\n\n']
    out += [f'- `{lib}`: {", ".join(users)}\n' for lib, users in sorted(plan.core_libs.items())] or ['- none\n']

    out += ['\n## Plugins that depend on each other\n',
            'Gradle cannot build a cycle, so these tiers compile together in the first one\'s project. Each still has its\n'
            'own directory, tests and jar; the second project only packages and tests its part.\n\n']
    out += [f'- {", ".join("`" + plan_mod.node_name(n) + "`" for n in c)} (compiled in `:plugins:{c[0][0]}:{c[0][1]}`)\n'
            for c in plan.cycles] or ['- none\n']

    out += ['\n## Core tests that use plugins\n',
            'Core tests exercise plugin classes, either directly or through core code that names them (migrations, default\n'
            'configuration, XStream documents), so `server` has a test-scope dependency on these. Main code is unaffected.\n'
            'A test whose subject is a plugin class lives with the plugin (`model.OWNERSHIP_OVERRIDES`). These stay because the\n'
            'subject is core and the plugin class is its input: the script builders need real step and rule types, the JSON and\n'
            'XML serializers need real connector properties, and the shared fixtures (`TestUtils`, `TestServer`) wire up a VM channel.\n\n']
    out += [f'- `testImplementation :plugins:{e}:{t}`\n' for e, t in sorted(plan.core_test_deps)] or ['- none\n']

    out += ['\n## Other structural changes\n',
            '- `server/setup` and `server/dist` are now `distribution/setup` and `distribution/dist`; `createDerbyDb` and\n'
            '  `devLauncher` moved to `:distribution`. The signing keystore and manifest moved with them.\n'
            '- The core jars are built into `server/build/libs` and copied into `setup/` by `:distribution`.\n'
            '- A plugin tier compiles against all of `server`; nothing stops a `common` class from reaching a server-only\n'
            '  core class, only that it would fail to load in the Administrator.\n'
            '- Third-party libraries still come from the shared `server-main`/`client-main` bundles; only the libraries that\n'
            '  were already per extension (`server-extensions`) moved into the owning plugin.\n'
            '- Plugins ship their own user API sources (`extensions/<name>/src/<name>-userutil-sources.jar`, registered in their\n'
            '  descriptor); the javadoc for those packages is built by `:distribution` from `plugins/<name>`.\n']
    return ''.join(out)
